		var trimmed = newTitle.trim();
		if (trimmed === '') {
			destroyTodo(id);
			return;
		}
		var todo = findTodoById(id);
		if (todo) {
			todo.title = trimmed;
			editingId = null;
			save();
			render();
		}
	}

